// A quién se avisa de una tarea que Lucía acaba de anotar.
//
// Regla: a quien la tenga asignada, si recibe avisos por WhatsApp. Si no está asignada a
// nadie -- lo normal: solo se asigna cuando el cliente nombra a alguien -- o esa persona
// no recibe avisos, a TODOS los que los reciben. Mejor que se entere uno de más que nadie:
// el problema que esto resuelve es una petición que se queda sin contestar.
//
// "Recibe avisos" es el mismo interruptor que el resumen de las 8:00
// (employees.whatsapp_notifications), activo y con teléfono. No hay otro ajuste.
//
// Si una consulta a Directus falla, se falla A LA VISTA (como en el resumen): no avisar
// porque un 403 devolvió una lista vacía es justo el silencio que esto viene a quitar.
const lista = (nombre, uno) => {
  const r = $(nombre).first().json || {};
  const code = r.statusCode || 0;
  if (code < 200 || code >= 300) {
    const msg = (r.body && r.body.errors && r.body.errors[0] && r.body.errors[0].message) || code;
    throw new Error(`${nombre}: Directus devolvió ${code} (${msg})`);
  }
  return uno ? ((r.body && r.body.data) || null) : ((r.body && r.body.data) || []);
};
const tarea = lista('HTTP · Tarea', true);
const empleados = lista('HTTP · Empleados', false);
const entrada = $('When Executed by Another Workflow').first().json || {};

if (!tarea) return [{ json: { _nadie: true, motivo: 'tarea_no_encontrada' } }];

// Meta rechaza en una variable saltos de línea, tabuladores y más de 4 espacios seguidos,
// y una variable vacía. Se aplana y se recorta.
const plano = (v, max) => {
  const s = (v === undefined || v === null ? '' : String(v)).replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
};

const c = (tarea.contact_id && typeof tarea.contact_id === 'object') ? tarea.contact_id : {};
const nombre = [c.first_name, c.last_name].filter(Boolean).join(' ');
const empresa = (c.company || '').trim();
const cliente = plano(nombre ? (empresa ? `${nombre} (${empresa})` : nombre) : (empresa || 'un cliente'), 80);

const CANALES = { whatsapp: 'WhatsApp', voz: 'teléfono', webchat: 'el chat de la web' };
const canal = CANALES[String(entrada.canal || '').toLowerCase()] || 'mensaje';

const asunto = plano(tarea.title, 200) || 'tarea sin título';

const conAvisos = empleados.filter((e) => e.phone_normalized || e.phone);
const asignado = tarea.assignee_id
  ? conAvisos.find((e) => e.id === (typeof tarea.assignee_id === 'object' ? tarea.assignee_id.id : tarea.assignee_id))
  : null;
const destinatarios = asignado ? [asignado] : conAvisos;

if (!destinatarios.length) {
  return [{ json: { _nadie: true, motivo: 'nadie_recibe_avisos',
    detalle: 'Ningún empleado activo tiene "whatsapp_notifications" y teléfono.' } }];
}
return destinatarios.map((e) => ({ json: {
  telefono: e.phone_normalized || e.phone,
  plantilla: 'aegora_aviso_tarea',
  parametros: JSON.stringify([cliente, canal, asunto]),
  contact_id: '',
  _empleado: e.first_name || e.id,
  _por: asignado ? 'asignada' : 'todos',
} }));
